import os
import re
from typing import Dict, Iterable, Tuple, Set, List
import json

# --- Configuration Management ---
# Externalize exclusion rules for better maintainability and dynamic updates.
# In a real system, this would be loaded from a config file, environment, or a central service.

# Default values for demonstration.
DEFAULT_EXCLUDED_DIR_SEGMENTS = {'.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints'}
DEFAULT_EXCLUDED_DIR_SUFFIXES = {'.egg-info', '.dist-info'}

def load_exclusion_config(config_path: str = None) -> Tuple[Set[str], Set[str]]:
    """Loads exclusion rules from a JSON configuration file."""
    if config_path and os.path.exists(config_path):
        try:
            with open(config_path, 'r') as f:
                config = json.load(f)
            segments = set(config.get('excluded_dir_segments', []))
            suffixes = set(config.get('excluded_dir_suffixes', []))
            return segments, suffixes
        except json.JSONDecodeError as e:
            print(f"Warning: Could not parse config file {config_path}: {e}. Using default exclusions.")
        except Exception as e:
            print(f"Warning: Error loading config file {config_path}: {e}. Using default exclusions.")
    return DEFAULT_EXCLUDED_DIR_SEGMENTS, DEFAULT_EXCLUDED_DIR_SUFFIXES

# Load exclusions globally or pass them around. For this module, we'll load once.
_EXCLUDED_DIR_SEGMENTS, _EXCLUDED_DIR_SUFFIXES = load_exclusion_config()

# --- Path Validation & Sanitization ---

# Regex for common invalid characters in filenames (more strict for Windows)
# This is a basic example; real-world might need OS-specific regex.
INVALID_FILENAME_CHARS_REGEX = re.compile(r'[<>:"/\\|?*\x00-\x1f]')

def is_generated_path(path: str) -> bool:
    """True if the path lives inside a machine-generated directory.
    Checks are case-insensitive for segments to improve robustness across OS.
    """
    parts = path.split(os.path.sep)
    for part in parts:
        part_lower = part.lower() # Case-insensitive check for segments
        if part_lower in _EXCLUDED_DIR_SEGMENTS:
            return True
        for suffix in _EXCLUDED_DIR_SUFFIXES:
            if part_lower.endswith(suffix):
                return True
    return False

def is_malformed_path(path: str) -> bool:
    """True if markdown formatting, stray whitespace, or invalid characters leaked into the filename.
    This is a broader check than the original.
    """
    # Check for original malformation (markdown/whitespace)
    if sanitize_path_cosmetic(path) != path:
        return True
    # Check for invalid filesystem characters
    if INVALID_FILENAME_CHARS_REGEX.search(path):
        return True
    # Check for path traversal attempts (e.g., '..')
    if '..' in path.split(os.path.sep):
        return True
    # Consider checking for absolute paths if only relative are expected
    if os.path.isabs(path):
        # Depending on context, absolute paths might be malformed if only relative are allowed
        # For this example, we'll flag it as malformed if it's absolute and not just a root.
        if path != os.path.abspath(os.path.sep): # Exclude root path itself
            return True
    return False

def sanitize_path_cosmetic(path: str) -> str:
    """Strips markdown decoration and leading/trailing whitespace from an agent-supplied path.
    This is a cosmetic fix, not a security sanitizer.
    """
    return path.strip().strip(' *_`')

def validate_path_for_security(path: str) -> bool:
    """Performs strict security validation on a path before any filesystem operation.
    Returns True if the path is considered safe for use in filesystem operations.
    """
    if not isinstance(path, str):
        return False

    # 1. Check for empty path
    if not path:
        return False

    # 2. Check for path traversal attempts
    normalized_path = os.path.normpath(path)
    if normalized_path.startswith('..') or '/../' in normalized_path or '\\..\\' in normalized_path:
        return False

    # 3. Check for absolute paths (if only relative are allowed)
    # This depends on context. For artifact bundles, often only relative paths are expected.
    if os.path.isabs(path):
        # If absolute paths are strictly forbidden, return False.
        # For this example, we allow absolute paths if they don't traverse.
        pass 

    # 4. Check for invalid characters
    if INVALID_FILENAME_CHARS_REGEX.search(path):
        return False

    # 5. Check for reserved names (e.g., CON, PRN on Windows) - more complex, OS-specific
    # Not implemented here for brevity, but a real system would consider this.

    return True

# --- Bundle Processing Functions ---

def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
    """Returns only genuinely agent-authored files from a path->content map.
    Logs discarded files for auditing.
    """
    authored_files = {}
    for path, content in bundle.items():
        if not is_generated_path(path) and not is_malformed_path(path):
            if validate_path_for_security(path): # Crucial security check before considering it "authored"
                authored_files[path] = content
            else:
                print(f"WARNING: Path '{path}' failed security validation and was discarded from authored files.")
        else:
            # Log why it was discarded
            reason = []
            if is_generated_path(path):
                reason.append("generated")
            if is_malformed_path(path):
                reason.append("malformed")
            print(f"INFO: Path '{path}' discarded from authored files (Reason: {', '.join(reason)}).")
    return authored_files

def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str], Dict[str, str]]:
    """Splits a bundle into (authored, generated, malformed, security_rejected) for reporting.
    This is the recommended approach for comprehensive auditing.
    """
    authored: Dict[str, str] = {}
    generated: Dict[str, str] = {} # Corrected type hint
    malformed: Dict[str, str] = {}
    security_rejected: Dict[str, str] = {}

    for path, content in bundle.items():
        if is_generated_path(path):
            generated[path] = content
        elif is_malformed_path(path):
            malformed[path] = content
        elif not validate_path_for_security(path): # New category for paths failing security
            security_rejected[path] = content
        else:
            authored[path] = content

    return authored, generated, malformed, security_rejected

def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str]=('.py',)) -> int:
    """Counts authored files matching the given suffixes, after security validation."""
    authored_bundle = filter_bundle(bundle) # filter_bundle now includes security validation and logging
    suffix_tuple = tuple(suffixes)
    count = 0
    for path in authored_bundle:
        if path.endswith(suffix_tuple):
            count += 1
    return count

